# Code generated by Claude
"""The hollow glass beaker of the beaker-on-hotplate task, built into the model at load time through MjSpec.

    add_hollow_beaker(spec, cfg=BEAKER_CFG)        # RobotSimulator(spec_hooks=[...]) calls it before compiling

Same pattern as src/base_contacts.py: models/objects/beaker.xml only holds the body, its free joint and the site "beaker_base" at the body origin
(the bottom centre), and RobotSimulator applies this before compiling, so the size, the masses and the friction are settings of src/task_config.py
(BEAKER_CFG) and not numbers in the XML. The XML's solid cylinder (a fallback so the scene still loads without this module) is removed.

What it builds (all of it is rigid, one body):
  * the wall: a ring of `n_segments` thin boxes (collision and look; no hollow mesh), each as long as the chord of the ring at its mid radius so
    neighbours meet, `wall` thick, from the bottom disk up to `height`;
  * the bottom: a cylinder disk, `wall` thick;
  * the glass mass, shared by the wall segments and the bottom disk by volume (MuJoCo then gives the body its centre of mass and inertia);
  * the liquid: a separate rigid mass, a cylinder as wide as the inside and as tall as that mass of liquid fills (liquid_mass / liquid_density), sitting on the
    bottom, with no collision and no visuals (alpha 0). It only places the mass low in the beaker;
  * the contact pairs: every finger and palm geom of both hands against every wall and bottom geom, with the gripper friction of BEAKER_CFG["contact_friction"].
    The robot's gripper geoms have priority 1, so their friction (1.0) would win over the beaker's own and no beaker setting could change it; an explicit
    pair does. Everything else the beaker touches keeps the beaker's own friction (BEAKER_CFG["friction"]), mixed with the other surface's the usual way.
"""

import math

import mujoco

from src.task_config import BEAKER_CFG

FALLBACK_GEOM = "task_beaker_glass"          # the solid cylinder of models/objects/beaker.xml, replaced here


def beaker_dims(cfg=BEAKER_CFG):
    """Derived sizes of the beaker.

    Args:
        cfg (dict): The beaker configuration. Defaults to task_config.BEAKER_CFG.

    Returns:
        dict: With the keys "r_out", "r_mid", "r_in" (radii of the outside, the middle of the wall and the inside, metres), "bottom" (disk thickness, metres),
        "wall_h" (height of the wall segments, metres), "chord" (length of one wall segment, metres), "liquid_h" (height of the liquid column, metres; 0 when
        there is no liquid) and "height" (the beaker's height, metres).
    """
    r_out = cfg["outer_diameter"] / 2
    r_in = r_out - cfg["wall"]
    liquid_h = cfg["liquid_mass"] / (cfg["liquid_density"] * math.pi * r_in ** 2) if cfg["liquid_mass"] > 0 else 0.0
    r_mid = r_out - cfg["wall"] / 2
    return {"r_out": r_out, "r_mid": r_mid, "r_in": r_in, "bottom": cfg["wall"], "wall_h": cfg["height"] - cfg["wall"],
            "chord": 2 * r_mid * math.tan(math.pi / cfg["n_segments"]), "liquid_h": liquid_h, "height": cfg["height"]}


def add_hollow_beaker(spec, cfg=BEAKER_CFG):
    """Adds the beaker's geoms, the liquid mass and the gripper contact pairs to the spec.

    Args:
        spec (mujoco.MjSpec): The scene with the robot and models/objects/beaker.xml, not yet compiled.
        cfg (dict): The beaker configuration. Defaults to task_config.BEAKER_CFG.

    Returns:
        dict: beaker_dims(cfg) plus "n_pairs" (number of contact pairs added) and "geoms" (names of the beaker's geoms, wall segments then the bottom).

    Raises:
        ValueError: If the body, or a gripper geom named by the configuration, is not in the model; if the liquid would be taller than the beaker.
    """
    body = spec.body(cfg["body"])
    if body is None:
        raise ValueError(f"beaker body '{cfg['body']}' not found in the model")
    fallback = spec.geom(FALLBACK_GEOM)
    if fallback is not None:
        spec.delete(fallback)
    n, wall = cfg["n_segments"], cfg["wall"]
    dim = beaker_dims(cfg)
    if dim["liquid_h"] > dim["wall_h"]:
        raise ValueError(f"the liquid ({dim['liquid_h'] * 1000:.0f} mm) is taller than the beaker's inside ({dim['wall_h'] * 1000:.0f} mm)")
    v_wall = dim["chord"] * wall * dim["wall_h"]                       # one segment's volume
    v_bottom = math.pi * dim["r_out"] ** 2 * dim["bottom"]
    v_glass = n * v_wall + v_bottom
    glass = []
    for i in range(n):
        a = 2 * math.pi * i / n
        t = a + math.pi / 2                                            # the segment's long side runs along the tangent
        g = body.add_geom(name=f"{cfg['body']}_wall_{i}", type=mujoco.mjtGeom.mjGEOM_BOX,
                          size=[dim["chord"] / 2, wall / 2, dim["wall_h"] / 2],
                          pos=[dim["r_mid"] * math.cos(a), dim["r_mid"] * math.sin(a), dim["bottom"] + dim["wall_h"] / 2],
                          quat=[math.cos(t / 2), 0.0, 0.0, math.sin(t / 2)],
                          mass=cfg["glass_mass"] * v_wall / v_glass, friction=list(cfg["friction"]), rgba=list(cfg["rgba"]))
        glass.append(g.name)
    g = body.add_geom(name=f"{cfg['body']}_bottom", type=mujoco.mjtGeom.mjGEOM_CYLINDER, size=[dim["r_out"], dim["bottom"] / 2, 0.0],
                      pos=[0.0, 0.0, dim["bottom"] / 2], mass=cfg["glass_mass"] * v_bottom / v_glass, friction=list(cfg["friction"]), rgba=list(cfg["rgba"]))
    glass.append(g.name)
    if cfg["liquid_mass"] > 0:                                          # a mass only: no collision, invisible
        body.add_geom(name=f"{cfg['body']}_liquid", type=mujoco.mjtGeom.mjGEOM_CYLINDER, size=[dim["r_in"], dim["liquid_h"] / 2, 0.0],
                      pos=[0.0, 0.0, dim["bottom"] + dim["liquid_h"] / 2], mass=cfg["liquid_mass"], contype=0, conaffinity=0, group=4,
                      rgba=[0.0, 0.0, 0.0, 0.0])
    n_pairs = 0
    for side in ("left", "right"):
        for gripper_geom in cfg["gripper_geoms"]:
            name = f"openarm_{side}_{gripper_geom}"
            if spec.geom(name) is None:
                raise ValueError(f"gripper geom '{name}' (BEAKER_CFG['gripper_geoms']) not found in the model")
            for beaker_geom in glass:
                p = spec.add_pair()
                p.geomname1, p.geomname2 = name, beaker_geom
                p.condim = 3
                p.friction = [cfg["contact_friction"][0], cfg["contact_friction"][0], cfg["contact_friction"][1], cfg["contact_friction"][2],
                              cfg["contact_friction"][2]]
                p.solref = list(cfg["contact_solref"])
                p.solimp = list(cfg["contact_solimp"])
                n_pairs += 1
    return {**dim, "n_pairs": n_pairs, "geoms": glass}
